// Merge EXTRA2 (English) and T (other langs) into STRINGS
Object.keys(EXTRA2).forEach(lc => {
  if (STRINGS[lc]) STRINGS[lc] = { ...STRINGS[lc], ...EXTRA2[lc] };
});
Object.keys(T).forEach(lc => {
  if (STRINGS[lc]) STRINGS[lc] = { ...STRINGS[lc], ...T[lc] };
});
Object.keys(ROUND12).forEach(lc => {
  if (STRINGS[lc]) STRINGS[lc] = { ...STRINGS[lc], ...ROUND12[lc] };
});


export const t = (lang, key, vars = {}) => {
  const tbl = STRINGS[lang] || STRINGS["en-GB"];
  let s = tbl[key];
  if (s === undefined) s = STRINGS["en-GB"][key];
  if (s === undefined) s = key;
  Object.entries(vars).forEach(([k, v]) => { s = s.replace(`{${k}}`, v); });
  return s;
};

export const RTL_LANGS = ["ar-IQ", "ur-PK"];
